-- LensFlow UAT + SUS: FIVE SYNTHETIC TEST SUBMISSIONS
-- Use ONLY to test database storage and reporting. NOT real research evidence.
-- Scores are GENERATED by the existing database schema, not inserted directly.
-- Safe to rerun: participant_id conflict is ignored.

WITH mock_participants (
    participant_id, device_browser, sus_answers, uat_feedback, sus_feedback, assisted_tasks
) AS (
    VALUES
    (
      'MOCK-UAT-001', 'Desktop / Chrome',
      ARRAY[5,1,5,2,4,1,5,1,4,1]::integer[],
      jsonb_build_object('incomplete_tasks', 'None', 'errors', 'No errors encountered.', 'missing_features', 'No major missing features.'),
      jsonb_build_object('easiest', 'The dashboard and service creation were intuitive.', 'most_difficult', 'The gallery download permissions button took some time to locate.', 'improvements', 'Make gallery settings more prominent and add clearer button labels.', 'future_use', 'Yes. It would simplify routine photography administration.'),
      ARRAY[10]::integer[]
    ),
    (
      'MOCK-UAT-002', 'Laptop / Edge',
      ARRAY[4,2,4,2,5,1,4,2,5,1]::integer[],
      jsonb_build_object('incomplete_tasks', 'None', 'errors', 'No functional errors.', 'missing_features', 'Initially unsure where to find invoice PDF.'),
      jsonb_build_object('easiest', 'Finding clients and editing photography services.', 'most_difficult', 'The invoice PDF action was not immediately obvious.', 'improvements', 'Add a more visible Download PDF button on the invoice page.', 'future_use', 'Yes, particularly for bookings and invoices.'),
      ARRAY[7]::integer[]
    ),
    (
      'MOCK-UAT-003', 'Desktop / Firefox',
      ARRAY[4,2,5,2,4,2,4,1,5,2]::integer[],
      jsonb_build_object('incomplete_tasks', 'None', 'errors', 'Needed clarification for availability exception.', 'missing_features', 'No essential features missing.'),
      jsonb_build_object('easiest', 'Navigating the main sidebar and managing bookings.', 'most_difficult', 'Adding an unavailable date to the calendar.', 'improvements', 'Make the Add Unavailable Date action easier to discover.', 'future_use', 'Yes, once familiar with the calendar controls.'),
      ARRAY[5]::integer[]
    ),
    (
      'MOCK-UAT-004', 'Laptop / Chrome',
      ARRAY[5,2,5,2,4,1,4,1,5,1]::integer[],
      jsonb_build_object('incomplete_tasks', 'None', 'errors', 'No errors encountered.', 'missing_features', 'Website editing controls could be clearer.'),
      jsonb_build_object('easiest', 'Creating services and messaging clients.', 'most_difficult', 'Finding the Save Changes action in website management.', 'improvements', 'Use a persistent save button and show a clear saved confirmation.', 'future_use', 'Yes. Most tasks were straightforward.'),
      ARRAY[12]::integer[]
    ),
    (
      'MOCK-UAT-005', 'Desktop / Safari',
      ARRAY[5,1,4,2,5,1,4,1,5,1]::integer[],
      jsonb_build_object('incomplete_tasks', 'None', 'errors', 'No critical errors.', 'missing_features', 'Could not immediately identify the gallery publish control.'),
      jsonb_build_object('easiest', 'Client records, booking overview and dashboard navigation.', 'most_difficult', 'Locating the Publish Gallery button.', 'improvements', 'Make primary actions visually consistent across pages.', 'future_use', 'Yes. The overall workflow felt well integrated.'),
      ARRAY[9]::integer[]
    )
)
INSERT INTO public.uat_submissions (
    participant_id, device_browser, task_results,
    uat_feedback, sus_answers, sus_feedback
)
SELECT
    p.participant_id,
    p.device_browser,
    (
      SELECT jsonb_agg(
        jsonb_build_object(
          'task_id', 'UAT' || lpad(task_no::text, 2, '0'),
          'status', CASE WHEN task_no = ANY(p.assisted_tasks)
                         THEN 'Pass with assistance' ELSE 'Pass' END,
          'notes', CASE WHEN task_no = ANY(p.assisted_tasks)
                        THEN 'Completed after a hint about where to find the control.'
                        ELSE 'Completed without assistance.' END
        ) ORDER BY task_no
      )
      FROM generate_series(1, 12) AS task_no
    ),
    p.uat_feedback,
    p.sus_answers,
    p.sus_feedback
FROM mock_participants AS p
ON CONFLICT (participant_id) DO NOTHING;

-- Verify inserted records and their GENERATED SUS scores.
SELECT participant_id, created_at, sus_score,
       jsonb_array_length(task_results) AS task_count,
       sus_feedback->>'improvements' AS suggested_improvement
FROM public.uat_submissions
WHERE participant_id LIKE 'MOCK-UAT-%'
ORDER BY participant_id;

